import{_ as o,o as t,c as r,a5 as n}from"./chunks/framework.DJo0M80U.js";const f=JSON.parse('{"title":"next() 作用","description":"在 Vue Router 的 beforeEach 导航守卫中， next 函数用于控制导航的流程。它的调用方式有多种，可以传入不同的参数来执行不同的导航行为。 next 函数的调用方法和参数 next()调用后，不会再进入beforeEach； next(arg)带参数的调用。","frontmatter":{"title":"next() 作用","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","路由与状态管理"],"description":"在 Vue Router 的 beforeEach 导航守卫中， next 函数用于控制导航的流程。它的调用方式有多种，可以传入不同的参数来执行不同的导航行为。 next 函数的调用方法和参数 next()调用后，不会再进入beforeEach； next(arg)带参数的调用。","sidebarWeight":24,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/vueRouter/vue2中引入vue-router/next() 作用.md"},"headers":[],"relativePath":"posts/Vue系统教程/04-路由与状态管理/vue2中引入vue-router/next() 作用.md","filePath":"posts/Vue系统教程/04-路由与状态管理/vue2中引入vue-router/next() 作用.md"}'),c={name:"posts/Vue系统教程/04-路由与状态管理/vue2中引入vue-router/next() 作用.md"};function a(d,e,l,x,i,u){return t(),r("div",null,[...e[0]||(e[0]=[n('<div><h1 id="next-作用" tabindex="-1">next() 作用 <a class="header-anchor" href="#next-作用" aria-label="Permalink to &quot;next() 作用&quot;">​</a></h1><blockquote><p>本节目标：理解“next() 作用”的核心思路，并能把它用于实际开发或面试表达。 在 Vue Router 的 <code>beforeEach</code> 导航守卫中，<code>next</code> 函数用于控制导航的流程。它的调用方式有多种，可以传入不同的参数来执行不同的导航行为。 <code>next</code> 函数的调用方法和参数</p></blockquote><ul><li>next()调用后，不会再进入beforeEach；</li><li>next(arg)带参数的调用，会再次进入beforeEach，处理不好会死循环；</li></ul><ol><li><p><code>next()</code> 无参数调用 <code>next</code>，表示允许导航继续。 router.beforeEach((to, from, next) =&gt; { next(); // 允许导航 });</p></li><li><p><code>next(false)</code> 传入 <code>false</code> 来取消当前导航。如果浏览器的 URL 已经改变（通常是用户手动输入 URL 或点击浏览器的前进/后退按钮），当取消导航后，URL 会重置到 <code>from</code> 路由对应的地址。 router.beforeEach((to, from, next) =&gt; { next(false); // 取消导航 });</p></li><li><p><code>next(&#39;/&#39;)</code> 或 <code>next({ path: &#39;/&#39; })</code> 传入一个字符串路径或者一个描述目标位置的对象，来重定向导航。 router.beforeEach((to, from, next) =&gt; { next(&#39;/&#39;); // 重定向到首页 // 或者 next({ path: &#39;/&#39; }); });</p></li><li><p><code>next({ path: &#39;/&#39;, replace: true })</code> 使用 <code>replace</code> 选项来重定向并且不会在浏览器历史记录中留下记录。 router.beforeEach((to, from, next) =&gt; { next({ path: &#39;/&#39;, replace: true }); // 重定向到首页，不留下历史记录 }); ==next()== 会跳出 ==beforeEach==, 并且跳转到我们想去的组件,但是 ==next({ ...to, replace: true });== 不会,它会再次进入 ==beforeEach== 这个函数, 然后 就会陷入死循环.</p></li><li><p><code>next({ name: &#39;home&#39; })</code> 传入一个命名路由对象来重定向导航。 router.beforeEach((to, from, next) =&gt; { next({ name: &#39;home&#39; }); // 重定向到名为 &#39;home&#39; 的路由 });</p></li><li><p><code>next(new Error(&#39;navigation error&#39;))</code> 传入一个 <code>Error</code> 实例，导航会被终止，同时会调用 <code>router.onError</code> 注册的回调。 router.beforeEach((to, from, next) =&gt; { next(new Error(&#39;navigation error&#39;)); // 终止导航并触发错误 });</p></li></ol><p>总结</p><ul><li><code>next()</code>：继续导航</li><li><code>next(false)</code>：取消导航</li><li><code>next(&#39;/&#39;)</code> 或 <code>next({ path: &#39;/&#39; })</code>：重定向到指定路径</li><li><code>next({ path: &#39;/&#39;, replace: true })</code>：重定向并替换当前记录</li><li><code>next({ name: &#39;home&#39; })</code>：重定向到命名路由</li><li><code>next(new Error(&#39;navigation error&#39;))</code>：抛出导航错误 通过这些调用方式，你可以灵活控制 Vue Router 中的导航行为。</li></ul></div>',1)])])}const s=o(c,[["render",a]]);export{f as __pageData,s as default};
